<script setup lang="ts">
import { ref, watch } from 'vue'; import type { LibraryDto } from '../../api/contracts'; import { useTasksStore } from '../../stores/tasks'; import BackgroundTaskProgress from '../tasks/BackgroundTaskProgress.vue';
const props = defineProps<{ libraries: LibraryDto[]; count: number | null; countError: string }>(); const emit = defineEmits<{ query: [libraryId: number, onlyMissing: boolean]; run: [payload: Record<string, unknown>]; avatar: [libraryId: number] }>();
const tasks = useTasksStore(), library = ref(0), onlyMissing = ref(true), force = ref(false);
watch([library, onlyMissing], ([lib, missing]) => emit('query', Number(lib), missing), { immediate: true });
</script>
<template><section class="panel"><div class="panel-head"><h2>立即刮削</h2><div class="panel-actions"><span id="scrape-count" class="hint" style="margin:0">{{ countError || (count == null ? '正在读取候选数…' : `本次将处理 ${count} 条`) }}</span></div></div><div class="filters"><select id="sc-lib" v-model.number="library" aria-label="刮削媒体库"><option :value="0">全部媒体库</option><option v-for="lib in libraries" :key="lib.Id" :value="lib.Id">{{ lib.Name }}</option></select><label class="check"><input id="sc-only-missing" v-model="onlyMissing" type="checkbox"> 仅处理缺失元数据的影片</label><label class="check"><input id="sc-force" v-model="force" type="checkbox"> 本次强制覆盖</label><button id="scrape-start" class="btn btn-accent btn-sm" :disabled="tasks.mutationBusy" @click="emit('run', {library_id:Number(library), only_missing:onlyMissing, overwrite:force})">开始刮削</button><button id="scrape-cancel" class="btn btn-sm" :disabled="!tasks.scrape.progress?.running || tasks.scrape.cancelling" @click="tasks.scrape.cancel()">中止</button><button id="avatar-start" class="btn btn-sm" :disabled="tasks.mutationBusy" @click="emit('avatar', Number(library))">补演员头像</button></div><BackgroundTaskProgress kind="scrape" :progress="tasks.scrape.progress" :visible="tasks.scrape.visible" :busy="tasks.scrape.busy" :unavailable="tasks.scrape.unavailable" :cancelling="tasks.scrape.cancelling" @cancel="tasks.scrape.cancel()" /><p class="hint">批量与定时为全自动：遇到「非番号精确命中」会跳过并标记「待人工确认」，可在媒体墙按刮削结果筛出后逐条手动处理。</p></section></template>
